//! Groups similar functions around a template (medoid) instead of chaining pairs, so
//! dissimilar bodies cannot be linked through a middleman (no transitive union-find).

use crate::align::{Alignment, Ctx, HoleKind, align};
use crate::facts::{NodeKind, Pdg};
use crate::normalize::{Rules, canonicalize_or_borrow};
use crate::wl::{SimilarityKey, Wl, call_class, comparable, similarity_milli};
use std::cmp::Reverse;
use std::collections::{BTreeMap, BTreeSet};

/// Blocks larger than this are skipped: their key is too common to say anything.
const BLOCK_CAP: usize = 1000;
/// How many of a function's rarest call classes are used as blocking keys.
const BLOCK_KEYS: usize = 2;
/// Corpora up to this size compare every pair: blocking on the rarest call classes picks
/// classes unique to each function when the corpus is tiny, so parallel functions never meet.
const ALL_PAIRS_LIMIT: usize = 400;

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Params {
    pub threshold_milli: u32,
    pub min_coverage_milli: u32,
    /// Experiment: also select pairs whose alignment coverage reaches this (besides WL similarity).
    #[serde(deserialize_with = "serde::Deserialize::deserialize")]
    pub pair_coverage_milli: Option<u32>,
    /// Canonicalization rules applied to every graph before hashing and aligning (default: none).
    pub normalize: Rules,
    /// Experiment: bodies with one call count as substantial unless that call only forwards parameters.
    pub single_call_guard: bool,
    /// More differing parts than this and a `parameterize` helper would take a parameter per line.
    pub max_holes: usize,
}

impl Default for Params {
    fn default() -> Self {
        Params {
            threshold_milli: 600,
            min_coverage_milli: 600,
            pair_coverage_milli: None,
            normalize: Rules::default(),
            single_call_guard: false,
            max_holes: 3,
        }
    }
}

/// One hole variable across all members: `values[k]` belongs to `Cluster::members[k]`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Column {
    pub kind: HoleKind,
    pub var: String,
    pub values: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cluster {
    /// Indices into the input slice; the template comes first, the rest ascending.
    pub members: Vec<usize>,
    pub coverage_milli: Vec<u32>,
    pub columns: Vec<Column>,
    /// Every retained alignment only forwards through distinct, single-use callee holes.
    /// Missing identities, shared calls, repeated holes or other node kinds keep this false.
    pub forwarding_only: bool,
    /// At least one retained member contains an opaque ordinary closure node.
    pub opaque_closure: bool,
}

fn classes_of(pdg: &Pdg) -> BTreeSet<String> {
    let calls = pdg.nodes.iter().filter(|n| n.kind == NodeKind::Call);
    calls.map(call_class).collect()
}

/// The rarest call classes (across the corpus) of every function.
fn block_keys(pdgs: &[&Pdg]) -> Vec<Vec<String>> {
    let sets: Vec<BTreeSet<String>> = pdgs.iter().map(|p| classes_of(p)).collect();
    let mut freq: BTreeMap<&str, usize> = BTreeMap::new();
    for class in sets.iter().flatten() {
        *freq.entry(class.as_str()).or_default() += 1;
    }
    sets.iter()
        .map(|set| {
            let mut ranked: Vec<&String> = set.iter().collect();
            ranked.sort_by_key(|c| (freq[c.as_str()], c.as_str()));
            ranked.into_iter().take(BLOCK_KEYS).cloned().collect()
        })
        .collect()
}

type Adjacency = BTreeMap<usize, BTreeSet<usize>>;

fn candidate_pairs(keys: &[Vec<String>]) -> BTreeSet<(usize, usize)> {
    let mut blocks: BTreeMap<&str, Vec<usize>> = BTreeMap::new();
    for (index, list) in keys.iter().enumerate() {
        for key in list {
            blocks.entry(key).or_default().push(index);
        }
    }
    blocks
        .values()
        .filter(|members| members.len() <= BLOCK_CAP)
        .flat_map(|members| {
            members
                .iter()
                .enumerate()
                .flat_map(|(i, a)| members[i + 1..].iter().map(move |b| (*a, *b)))
        })
        .collect()
}

/// Every pair for small corpora, pairs that share a blocking key otherwise.
fn pairs_to_compare(pdgs: &[&Pdg]) -> BTreeSet<(usize, usize)> {
    if pdgs.len() > ALL_PAIRS_LIMIT {
        return candidate_pairs(&block_keys(pdgs));
    }
    (0..pdgs.len())
        .flat_map(|a| (a + 1..pdgs.len()).map(move |b| (a, b)))
        .collect()
}

/// A comparable pair whose WL similarity reaches the threshold, or (experiment) whose
/// alignment coverage reaches `pair_coverage_milli`.
fn pair_selected(pdgs: &[&Pdg], wls: &[Wl], (a, b): (usize, usize), params: &Params) -> bool {
    if !comparable(&wls[a], &wls[b]) {
        return false;
    }
    similarity_milli(&wls[a], &wls[b]) >= params.threshold_milli
        || params.pair_coverage_milli.is_some_and(|floor| {
            let ctx = Ctx::new(pdgs[a], &wls[a], pdgs[b], &wls[b]);
            align(&ctx).coverage_milli >= floor
        })
}

/// Functions whose kernel similarity reaches the threshold, after the size filters.
fn similar(
    pdgs: &[&Pdg],
    wls: &[Wl],
    pairs: &BTreeSet<(usize, usize)>,
    params: &Params,
) -> Adjacency {
    let mut adjacency = Adjacency::new();
    for &(a, b) in pairs {
        if pair_selected(pdgs, wls, (a, b), params) {
            adjacency.entry(a).or_default().insert(b);
            adjacency.entry(b).or_default().insert(a);
        }
    }
    adjacency
}

/// Unassigned function with the most unassigned neighbours (lowest index on ties).
fn next_seed(adjacency: &Adjacency, free: &BTreeSet<usize>) -> Option<usize> {
    free.iter()
        .map(|v| {
            let degree = adjacency.get(v).map_or(0, |n| n.intersection(free).count());
            (degree, *v)
        })
        .filter(|(degree, _)| *degree > 0)
        .min_by_key(|(degree, v)| (usize::MAX - degree, *v))
        .map(|(_, v)| v)
}

/// Members with equal similarity keys, collapsed into one weighted class.
struct Classes {
    /// `(representative, members)` per class, in order of first appearance.
    reps: Vec<(usize, u64)>,
    /// Class of each group member, by group position.
    of_member: Vec<usize>,
}

fn classes(wls: &[Wl], group: &[usize]) -> Classes {
    let mut index: BTreeMap<SimilarityKey<'_>, usize> = BTreeMap::new();
    let mut reps: Vec<(usize, u64)> = Vec::new();
    let mut of_member = Vec::with_capacity(group.len());

    for &v in group {
        let class = *index.entry(wls[v].similarity_key()).or_insert(reps.len());
        if class == reps.len() {
            reps.push((v, 0));
        }
        reps[class].1 += 1;
        of_member.push(class);
    }
    Classes { reps, of_member }
}

/// Total similarity of one member of each class to every other group member. Similarity
/// is symmetric, so each distinct pair of classes is scored once and credited to both.
fn class_totals(wls: &[Wl], reps: &[(usize, u64)]) -> Vec<u64> {
    let score = |a: usize, b: usize| u64::from(similarity_milli(&wls[a], &wls[b]));
    let mut totals = vec![0; reps.len()];
    for (i, &(a, size_a)) in reps.iter().enumerate() {
        let own = if size_a > 1 {
            (size_a - 1) * score(a, a)
        } else {
            0
        };
        let mut total = totals[i] + own;
        for (j, &(b, size_b)) in reps.iter().enumerate().skip(i + 1) {
            let s = score(a, b);
            total += size_b * s;
            totals[j] += size_a * s;
        }
        totals[i] = total;
    }
    totals
}

/// The group member with the highest total similarity to the others (lowest index on
/// ties). Group members are distinct indices.
///
/// Identical members are scored once as a weighted class, as when a sum over many equal
/// subproblems is evaluated once per distinct subproblem and scaled by its multiplicity.
fn medoid(wls: &[Wl], group: &[usize]) -> usize {
    let Classes { reps, of_member } = classes(wls, group);
    let totals = class_totals(wls, &reps);
    group
        .iter()
        .zip(&of_member)
        .min_by_key(|(v, class)| (Reverse(totals[**class]), **v))
        .map(|(v, _)| *v)
        .expect("group is non-empty")
}

struct Joined {
    index: usize,
    alignment: Alignment,
}

fn join(pdgs: &[&Pdg], wls: &[Wl], template: usize, member: usize) -> Joined {
    let ctx = Ctx::new(pdgs[template], &wls[template], pdgs[member], &wls[member]);
    Joined {
        index: member,
        alignment: align(&ctx),
    }
}

type ColumnKey = (HoleKind, String);

/// Template value -> (first template site, the value each joined member has there).
fn tabulate(joined: &[Joined]) -> BTreeMap<ColumnKey, (usize, Vec<Option<String>>)> {
    let mut table: BTreeMap<ColumnKey, (usize, Vec<Option<String>>)> = BTreeMap::new();
    for (k, member) in joined.iter().enumerate() {
        for hole in &member.alignment.holes {
            let slot = table
                .entry((hole.kind, hole.a.clone()))
                .or_insert((usize::MAX, vec![None; joined.len()]));
            slot.0 = slot.0.min(hole.sites[0].0);
            slot.1[k].get_or_insert_with(|| hole.b.clone());
        }
    }
    table
}

fn columns_of(joined: &[Joined]) -> Vec<Column> {
    let mut rows: Vec<_> = tabulate(joined).into_iter().collect();
    rows.sort_by_key(|((kind, a), (site, _))| (*site, *kind, a.clone()));
    let mut counts: BTreeMap<HoleKind, usize> = BTreeMap::new();
    rows.into_iter()
        .map(|((kind, template), (_, found))| {
            let n = counts.entry(kind).or_insert(0);
            *n += 1;
            let prefix = crate::align::Hole::var_name(kind, *n - 1);
            let values = std::iter::once(template.clone())
                .chain(
                    found
                        .into_iter()
                        .map(|v| v.unwrap_or_else(|| template.clone())),
                )
                .collect();
            Column {
                kind,
                var: prefix,
                values,
            }
        })
        .collect()
}

/// Reuse completed holes and call counts: with no fn-item/literal nodes, each callee
/// hole site is a call. Equality to the smaller call count accounts for every such call.
/// This is proposal policy about shared work, not a body-equivalence or purity proof.
fn forwards_calls(a: &Wl, b: &Wl, alignment: &Alignment) -> bool {
    let calls = a.calls.min(b.calls);
    a.forwarding_shape
        && b.forwarding_shape
        && calls > 0
        && alignment.holes.len() == calls
        && alignment.holes.iter().all(|hole| {
            matches!(hole.kind, HoleKind::Method | HoleKind::FreeFn) && hole.sites.len() == 1
        })
}

fn build(pdgs: &[&Pdg], wls: &[Wl], group: &[usize], params: &Params) -> Option<Cluster> {
    let template = medoid(wls, group);
    let joined: Vec<Joined> = group
        .iter()
        .filter(|v| **v != template)
        .map(|v| join(pdgs, wls, template, *v))
        .filter(|j| j.alignment.coverage_milli >= params.min_coverage_milli)
        .collect();
    (!joined.is_empty()).then(|| Cluster {
        members: std::iter::once(template)
            .chain(joined.iter().map(|j| j.index))
            .collect(),
        coverage_milli: std::iter::once(1000)
            .chain(joined.iter().map(|j| j.alignment.coverage_milli))
            .collect(),
        columns: columns_of(&joined),
        opaque_closure: wls[template].opaque_closure
            || joined.iter().any(|member| wls[member.index].opaque_closure),
        forwarding_only: joined
            .iter()
            .all(|member| forwards_calls(&wls[template], &wls[member.index], &member.alignment)),
    })
}

/// Clusters of structurally parallel functions, largest first. Each function lands in at
/// most one cluster; members must align with the template above the coverage floor.
pub fn cluster(pdgs: &[&Pdg], params: &Params) -> Vec<Cluster> {
    let canonical: Vec<_> = pdgs
        .iter()
        .map(|p| canonicalize_or_borrow(p, &params.normalize))
        .collect();
    let pdgs: Vec<&Pdg> = canonical.iter().map(|p| p.as_ref()).collect();
    let pdgs = pdgs.as_slice();
    let wls: Vec<Wl> = pdgs.iter().map(|p| Wl::new(p)).collect();
    let adjacency = similar(pdgs, &wls, &pairs_to_compare(pdgs), params);
    let mut free: BTreeSet<usize> = adjacency.keys().copied().collect();
    let mut found = Vec::new();

    while let Some(seed) = next_seed(&adjacency, &free) {
        let group: Vec<usize> = adjacency[&seed]
            .iter()
            .copied()
            .filter(|v| free.contains(v))
            .chain([seed])
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        match build(pdgs, &wls, &group, params) {
            Some(c) => {
                free.retain(|v| !c.members.contains(v));
                found.push(c);
            }
            None => {
                free.remove(&seed);
            }
        }
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::facts::{NodeKind, PdgNode, TyShape};
    use crate::pdgtest::*;

    fn animals() -> Vec<Pdg> {
        vec![
            emit_loop("Dog", "bark"),
            emit_loop("Cat", "meow"),
            emit_loop("Cow", "moo"),
        ]
    }

    fn run(pdgs: &[Pdg], params: &Params) -> Vec<Cluster> {
        let refs: Vec<&Pdg> = pdgs.iter().collect();
        cluster(&refs, params)
    }

    /// `emit_loop` plus `extra` getter calls on the loop item, each feeding the return.
    fn extended(ty: &str, extra: usize) -> Pdg {
        let mut pdg = emit_loop(ty, "base");
        for k in 0..extra {
            let call = pdg.nodes.len();
            pdg.nodes.push(getter_call(ty, &format!("extra{k}")));
            pdg.edges
                .extend([data(2, call, 0), ctrl(2, call, 0), data(call, 5, k + 1)]);
        }
        pdg
    }

    /// The original definition: every ordered pair scored separately.
    fn reference_medoid(wls: &[Wl], group: &[usize]) -> usize {
        let total = |v: usize| -> u32 {
            group
                .iter()
                .filter(|w| **w != v)
                .map(|w| similarity_milli(&wls[v], &wls[*w]))
                .sum()
        };
        group
            .iter()
            .copied()
            .min_by_key(|v| (u32::MAX - total(*v), *v))
            .expect("group is non-empty")
    }

    #[test]
    fn weighted_class_medoid_matches_pairwise_definition() {
        let pdgs = [
            extended("Dog", 0),
            extended("Cat", 2),
            permuted(&extended("Cow", 2), 3),
            extended("Pig", 1),
            extended("Hen", 4),
            permuted(&extended("Dog", 0), 1),
            extended("Elk", 2),
            extended("Owl", 1),
        ];
        let wls: Vec<Wl> = pdgs.iter().map(Wl::new).collect();
        // Every non-empty subset, in ascending and descending member order.
        for mask in 1u32..1 << pdgs.len() {
            let mut group: Vec<usize> = (0..pdgs.len()).filter(|i| mask >> i & 1 == 1).collect();
            assert_eq!(
                medoid(&wls, &group),
                reference_medoid(&wls, &group),
                "{group:?}"
            );
            group.reverse();
            assert_eq!(
                medoid(&wls, &group),
                reference_medoid(&wls, &group),
                "{group:?}"
            );
        }
        // Names are not labels and node order does not matter: repeated shapes share a class.
        let Classes { reps, of_member } = classes(&wls, &[0, 1, 2, 3, 4, 5, 6, 7]);
        assert_eq!(reps.len(), 4);
        assert_eq!(of_member, [0, 1, 1, 2, 3, 0, 1, 2]);
    }

    #[test]
    fn identical_majority_outweighs_a_distinct_member() {
        let pdgs = [extended("Hen", 4), extended("Dog", 1), extended("Cat", 1)];
        let wls: Vec<Wl> = pdgs.iter().map(Wl::new).collect();
        assert_eq!(medoid(&wls, &[0, 1, 2]), 1);
        assert_eq!(medoid(&wls, &[0, 2, 1]), 1, "ties keep the lowest index");
    }

    #[test]
    fn opaque_closure_summary_follows_only_retained_graph_members() {
        let mut pdgs = animals();
        assert!(
            run(&pdgs, &Params::default())
                .iter()
                .all(|c| !c.opaque_closure)
        );
        for pdg in &mut pdgs {
            pdg.nodes.push(node(NodeKind::Closure));
        }
        let clusters = run(&pdgs, &Params::default());
        assert_eq!(clusters.len(), 1);
        assert!(clusters[0].opaque_closure);
        assert_eq!(clusters[0].coverage_milli, [1000, 1000, 1000]);

        let mut ordinary = animals();
        ordinary.push(pdgs.pop().unwrap());
        let refs: Vec<_> = ordinary.iter().collect();
        let wls: Vec<_> = refs.iter().map(|pdg| Wl::new(pdg)).collect();
        let selected = build(&refs, &wls, &[0, 1, 2], &Params::default()).unwrap();
        assert!(!selected.opaque_closure);
    }

    #[test]
    fn three_way_cluster_columns() {
        let clusters = run(&animals(), &Params::default());
        assert_eq!(clusters.len(), 1);
        let c = &clusters[0];
        assert_eq!(c.members, [0, 1, 2]);
        assert_eq!(c.coverage_milli, [1000, 1000, 1000]);
        let cols: Vec<(&str, &[String])> = c
            .columns
            .iter()
            .map(|c| (c.var.as_str(), c.values.as_slice()))
            .collect();
        assert_eq!(cols[0].0, "T0");
        assert_eq!(cols[0].1, ["k::Dog", "k::Cat", "k::Cow"]);
        assert_eq!(cols[1].0, "M0");
        assert_eq!(cols[1].1, ["k::Dog::bark", "k::Cat::meow", "k::Cow::moo"]);
        assert_eq!(cols.len(), 2);
    }

    #[test]
    fn member_below_coverage_rejected() {
        let mut graphs = animals();
        let mut padded = emit_loop("Hen", "cluck");
        padded.nodes.extend([push_call(), push_call()]);
        graphs.push(padded);
        let loose = Params {
            threshold_milli: 500,
            min_coverage_milli: 900,
            ..Params::default()
        };
        let clusters = run(&graphs, &loose);
        assert_eq!(clusters[0].members, [0, 1, 2]);
        let strict_free = Params {
            min_coverage_milli: 700,
            ..loose
        };
        assert_eq!(run(&graphs, &strict_free)[0].members, [0, 1, 2, 3]);
    }

    /// Pads a graph with two calls whose signature class is unique to `tag`, so its two
    /// rarest call classes are not shared with any other function.
    fn with_private_calls(mut pdg: Pdg, tag: usize) -> Pdg {
        for k in 0..2 {
            let mut n = getter_call("Z", "z");
            if let Some(sig) = n.callee_sig.as_mut() {
                sig.params = vec![TyShape::Param(tag * 2 + k + 10)];
            }
            pdg.nodes.push(n);
        }
        pdg
    }

    #[test]
    fn small_corpus_compares_functions_without_a_shared_rare_call() {
        let graphs: Vec<Pdg> = [("Dog", "bark"), ("Cat", "meow")]
            .iter()
            .enumerate()
            .map(|(i, (t, m))| with_private_calls(emit_loop(t, m), i))
            .collect();
        let refs: Vec<&Pdg> = graphs.iter().collect();
        assert!(candidate_pairs(&block_keys(&refs)).is_empty());
        assert_eq!(pairs_to_compare(&refs).len(), 1);
    }

    #[test]
    fn large_corpus_falls_back_to_blocking() {
        let graphs: Vec<Pdg> = (0..=ALL_PAIRS_LIMIT)
            .map(|i| with_private_calls(emit_loop("Dog", "bark"), i))
            .collect();
        let refs: Vec<&Pdg> = graphs.iter().collect();
        assert!(pairs_to_compare(&refs).is_empty());
    }

    #[test]
    fn unrelated_functions_do_not_cluster() {
        let lone = Pdg {
            nodes: vec![
                push_call(),
                getter_call("Dog", "bark"),
                push_call(),
                push_call(),
            ],
            edges: vec![],
        };
        assert!(run(&[emit_loop("Dog", "bark"), lone], &Params::default()).is_empty());
    }

    #[test]
    fn pair_coverage_selects_pairs_the_wl_threshold_rejects() {
        let wl_off = Params {
            threshold_milli: 1001,
            ..Params::default()
        };
        assert!(run(&animals(), &wl_off).is_empty());
        let by_coverage = Params {
            pair_coverage_milli: Some(900),
            ..wl_off
        };
        assert_eq!(run(&animals(), &by_coverage).len(), 1);
    }

    /// `if ok { Err(E::Bad("x")) }` against `if ok { E::Bad }`: same decision, two spellings of the value.
    fn spelled_two_ways() -> Vec<Pdg> {
        use crate::facts::NodeKind::*;
        let lit = |kind: &str, text: &str| PdgNode {
            lit_kind: Some(kind.into()),
            detail: text.into(),
            ..node(Lit)
        };
        let ctor = || PdgNode {
            detail: "ctor".into(),
            ..node(Op)
        };
        let wrapped = Pdg {
            nodes: vec![
                node(Param),
                getter_call("T", "ok"),
                node(Branch),
                lit("str", "\"x\""),
                ctor(),
                ctor(),
                node(Return),
            ],
            edges: vec![
                data(0, 1, 0),
                data(1, 2, 0),
                ctrl(2, 4, 0),
                data(3, 4, 0),
                data(4, 5, 0),
                data(5, 6, 0),
            ],
        };
        let unit = Pdg {
            nodes: vec![
                node(Param),
                getter_call("T", "ok"),
                node(Branch),
                lit("path", "E::Bad"),
                node(Return),
            ],
            edges: vec![data(0, 1, 0), data(1, 2, 0), ctrl(2, 3, 0), data(3, 4, 0)],
        };
        vec![wrapped, unit]
    }

    #[test]
    fn normalize_rules_cluster_functions_that_spell_values_differently() {
        let strict = Params {
            threshold_milli: 900,
            min_coverage_milli: 900,
            ..Params::default()
        };
        assert!(run(&spelled_two_ways(), &strict).is_empty());
        let canonical = Params {
            normalize: Rules::ALL,
            ..strict
        };
        assert_eq!(run(&spelled_two_ways(), &canonical).len(), 1);
    }
}

//! Plain data passed from the rustc driver to the pure rule evaluator.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum EffectKind {
    Mutation,
    Io,
    Network,
    Global,
    Unsafe,
    Time,
    Random,
    Panic,
    Unknown,
}

impl EffectKind {
    pub fn name(self) -> &'static str {
        match self {
            Self::Mutation => "mutation",
            Self::Io => "io",
            Self::Network => "network",
            Self::Global => "global",
            Self::Unsafe => "unsafe",
            Self::Time => "time",
            Self::Random => "random",
            Self::Panic => "panic",
            Self::Unknown => "unknown",
        }
    }
}

/// Source budgets exclude lowered iterator bindings, while effects retain them.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MutationOrigin {
    #[default]
    Source,
    ForDesugaring,
}

/// A write to, or `&mut` borrow of, a place rooted at a local, param or `self`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MutationEvent {
    #[serde(default)]
    pub origin: MutationOrigin,
    pub root: String,
    /// Dotted field projections below `root` (empty when the root itself is mutated).
    pub field_path: String,
    pub line: usize,
    /// The write is observable outside the function: it goes through a `&mut`
    /// reference or raw pointer (`self`, `&mut` params). Mutating an owned
    /// local is state change for the mutation budget, but not a side effect.
    pub escapes: bool,
    /// Whole-object `&mut` reborrow of a workspace type (e.g. `self.helper()`):
    /// the callee performs the writes, so `escapes` is cleared and the call graph
    /// decides whether the caller inherits them.
    #[serde(default)]
    pub delegated: bool,
}

/// A call to a non-local function. Classified against the config by core, so
/// changing the config never requires re-running the compiler.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CallEvent {
    pub callee: String,
    pub line: usize,
    /// Dispatched through `dyn`, a fn pointer or a generic callable: the target is unknown.
    #[serde(default)]
    pub dynamic: bool,
    /// What the frontend's library contract says this call does, when it says anything.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub library: Option<LibraryClass>,
    /// The identity of a callee that's a library's, as a dependence graph names it. A comparison
    /// reads this, since `library` alone can't tell a library nothing classifies from this code.
    #[serde(default, skip_serializing)]
    pub library_callee: Option<String>,
}

/// What a library contract says a call does. Config can still override it, which is why
/// it stays on the call rather than becoming an effect here.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum LibraryClass {
    Pure,
    Effect(EffectKind),
}

/// An effect the driver can decide without any config (unsafe, static mut, dyn calls).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EffectEvent {
    pub kind: EffectKind,
    pub detail: String,
    pub line: usize,
}

/// Where a call-site argument comes from, as far as the driver can tell cheaply.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ArgSource {
    /// The caller's own parameter (0-based, `self` excluded), possibly behind `&`, `&mut` or `*`.
    Param(usize),
    /// A literal, `const`, `static` or enum/unit constructor path.
    Const,
    /// A field projection rooted at a local, parameter or `self` (`self.opts.verbose`).
    Field,
    Other,
}

/// An `if` whose `else` only returns, around a body that could stop being nested.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GuardClause {
    pub line: usize,
    /// Statements nested under the `if`.
    pub statements: usize,
}

/// A parameter of a function (`self` excluded).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ParamFacts {
    /// Binding name, `_` for destructuring patterns.
    pub name: String,
    /// Declared type as written, whitespace-collapsed.
    #[serde(rename = "type")]
    pub ty: String,
    /// Number of times the body mentions the binding. A parameter whose uses are all
    /// forwards to workspace callees is a pure pass-through.
    #[serde(default)]
    pub uses: usize,
    /// What it holds when that's a plain value, however it's passed. A type someone named says
    /// more than this, so it has none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scalar: Option<Scalar>,
}

/// A plain value a language gives its parameters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Scalar {
    Text,
    Integer,
    Float,
    Bool,
    Char,
}

impl Scalar {
    pub fn name(self) -> &'static str {
        match self {
            Self::Text => "text",
            Self::Integer => "integer",
            Self::Float => "float",
            Self::Bool => "bool",
            Self::Char => "char",
        }
    }
}

/// A call into workspace code (same crate or a sibling crate), by stable fn id.
/// Unlike `CallEvent` this includes same-crate callees; it is what the call graph is built from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Edge {
    /// Stable id of the callee (see `FnFacts::id`). For trait-method calls this
    /// is the trait method, not an impl: resolve via `FnFacts::implements`.
    pub callee: String,
    pub line: usize,
    /// Dispatched through `dyn`: the concrete impl is unknown.
    #[serde(default)]
    pub dynamic: bool,
    /// A trait declares the callee without a body, so only an implementation can run.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub required: bool,
    /// One entry per callee parameter (`self` excluded), in order.
    #[serde(default)]
    pub args: Vec<ArgSource>,
}

/// Structural shape of a type as written in a signature. Raw: nothing is
/// normalized here (no `Self` substitution, no positional variables); see `shape`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TyShape {
    /// Struct/enum/union by stable id (see `FnFacts::id`) with its type arguments.
    Adt {
        id: String,
        args: Vec<TyShape>,
    },
    Ref {
        mutable: bool,
        inner: Box<TyShape>,
    },
    Tuple(Vec<TyShape>),
    Slice(Box<TyShape>),
    Array(Box<TyShape>),
    /// bool, char, integers, floats, `str`, `!`.
    Prim(String),
    /// Generic parameter by index.
    Param(usize),
    FnPtr,
    /// `dyn Trait`, by principal trait id when there is one.
    Dyn(String),
    Opaque,
    Other,
}

/// How a method takes `self`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Receiver {
    /// Associated function without `self`.
    None,
    /// `self` / `mut self`.
    Value,
    /// `&self`.
    Ref,
    /// `&mut self`.
    RefMut,
    /// `self: Box<Self>`, `Rc<Self>`, `Pin<&mut Self>`, ...
    Other,
}

/// Raw signature facts of a function that lives in an `impl` block.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SigFacts {
    /// Id of the ADT the enclosing `impl` is for (`None` for free fns and non-ADT impls).
    #[serde(default)]
    pub self_ty: Option<String>,
    /// Type arguments of the impl's self type (`Transport<TcpStream>` -> `[TcpStream]`).
    #[serde(default)]
    pub self_args: Vec<TyShape>,
    pub receiver: Receiver,
    /// Parameter types, `self` excluded.
    #[serde(default)]
    pub params: Vec<TyShape>,
    pub ret: TyShape,
    #[serde(default)]
    pub is_async: bool,
    #[serde(default)]
    pub is_unsafe: bool,
    #[serde(default)]
    pub is_const: bool,
    /// Number of the function's own generic type parameters.
    #[serde(default)]
    pub generics: usize,
}

impl TyShape {
    /// Stable, distinct text for a type (not for display: ids are full paths).
    pub fn render(&self) -> String {
        let list = |items: &[TyShape]| {
            items
                .iter()
                .map(TyShape::render)
                .collect::<Vec<_>>()
                .join(", ")
        };
        match self {
            TyShape::Adt { id, args } if args.is_empty() => id.clone(),
            TyShape::Adt { id, args } => format!("{id}<{}>", list(args)),
            TyShape::Ref { mutable, inner } => {
                format!("&{}{}", if *mutable { "mut " } else { "" }, inner.render())
            }
            TyShape::Tuple(items) => format!("({})", list(items)),
            TyShape::Slice(inner) => format!("[{}]", inner.render()),
            TyShape::Array(inner) => format!("[{}; _]", inner.render()),
            TyShape::Prim(name) => name.clone(),
            TyShape::Param(index) => format!("T{index}"),
            TyShape::Dyn(id) => format!("dyn {id}"),
            TyShape::FnPtr => "fn".into(),
            TyShape::Opaque | TyShape::Other => "_".into(),
        }
    }
}

impl SigFacts {
    /// The type that owns the method: `self_ty` plus its concrete (non-`Param`) type arguments,
    /// so `impl Transport<TcpStream>` and `impl Transport<UnixStream>` are different owners.
    pub fn owner(&self) -> Option<String> {
        let id = self.self_ty.as_deref()?;
        let concrete: Vec<String> = self
            .self_args
            .iter()
            .filter(|a| !matches!(a, TyShape::Param(_)))
            .map(TyShape::render)
            .collect();
        Some(if concrete.is_empty() {
            id.to_string()
        } else {
            format!("{id}<{}>", concrete.join(", "))
        })
    }
}

/// Kind of a program-dependence-graph node. Front-end neutral: a MIR emitter could
/// produce the same kinds.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NodeKind {
    Param,
    /// Destructuring `let` / `if let` (simple `let x = e` is transparent: `x` is `e`'s node).
    Let,
    Call,
    Macro,
    Field,
    Lit,
    Branch,
    Match,
    /// `for` loops and `Iterator::for_each` closures: the same abstract iteration.
    Iterate,
    /// `while` and `loop`.
    Loop,
    Return,
    Try,
    /// Opaque: the body is not descended into.
    Closure,
    Cast,
    /// Operators, struct/tuple/array construction, indexing, assignment (see `detail`).
    Op,
    /// Canonical value construction (`normalize`): `Err(E::Bad("x"))`, `None`, `Ok(())` as one node.
    /// Never emitted by the driver.
    Ctor,
    /// Canonical decision (`normalize`): `if`, `else if`, `if let` and `match` as one node.
    Case,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EdgeKind {
    Data,
    Ctrl,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PdgNode {
    pub kind: NodeKind,
    /// Raw type of the value this node produces, when known.
    #[serde(default)]
    pub ty: Option<TyShape>,
    /// Stable id of the called function (`Call`, and `Lit` for fn items). Kept for hole detection.
    #[serde(default)]
    pub callee_id: Option<String>,
    /// Raw signature of the callee; core normalizes it into the node label (signature class).
    #[serde(default)]
    pub callee_sig: Option<SigFacts>,
    #[serde(default)]
    pub macro_name: Option<String>,
    #[serde(default)]
    pub lit_kind: Option<String>,
    /// Operator, field name or literal text; never part of the label.
    #[serde(default)]
    pub detail: String,
    #[serde(default)]
    pub line: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct PdgEdge {
    pub from: usize,
    pub to: usize,
    pub kind: EdgeKind,
    /// Operand position for data edges (receiver is 0), arm index for control edges.
    #[serde(default)]
    pub arg_pos: usize,
}

/// Dependence graph of one function body. No execution-order edges, so
/// reordering independent statements does not change it.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Pdg {
    pub nodes: Vec<PdgNode>,
    pub edges: Vec<PdgEdge>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FnFacts {
    /// Stable id: `<crate>::<def path>` with impl disambiguators (`{impl#0}`).
    /// Identical across lib/test targets, unlike the display `name`.
    #[serde(default)]
    pub id: String,
    /// For a trait-impl method, the id of the trait method it implements.
    #[serde(default)]
    pub implements: Option<String>,
    /// Workspace-relative path with `/` separators.
    pub path: String,
    pub line: usize,
    pub column: usize,
    pub name: String,
    /// Parameter count excluding `self`.
    pub params: usize,
    /// Name, type and use count of each parameter (`self` excluded).
    #[serde(default)]
    pub param_list: Vec<ParamFacts>,
    pub has_self: bool,
    pub statements: usize,
    /// Statements (plus the tail expression) directly in the body block; 1 for a
    /// non-block body. 0 in facts from older runs, which `fn_spacing` skips.
    #[serde(default)]
    pub top_statements: usize,
    /// Source-level complexity. Older facts omit it; absent data is unavailable.
    #[serde(default)]
    pub complexity: Option<crate::complexity::Measurement>,
    /// Source text from the `fn` signature through the closing brace.
    pub source: String,
    /// The comment line directly above the function (attributes skipped), if any.
    pub preceding_line: String,
    pub mutations: Vec<MutationEvent>,
    pub calls: Vec<CallEvent>,
    pub effects: Vec<EffectEvent>,
    /// Calls into workspace functions, in source order.
    #[serde(default)]
    pub edges: Vec<Edge>,
    /// Ids of workspace types this function writes through (sorted, deduplicated).
    #[serde(default)]
    pub mutated_types: Vec<String>,
    /// Signature shape; `None` for free functions and facts from older runs.
    #[serde(default)]
    pub sig: Option<SigFacts>,
    /// Each `if` that could be a guard clause.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub guard_clauses: Vec<GuardClause>,
    /// Dependence graph; only present when the driver ran in semantic (`patterns`) mode.
    #[serde(default)]
    pub pdg: Option<Pdg>,
    /// The terms its language's labels use. A label says them, so they aren't a fact to keep.
    #[serde(skip)]
    pub wording: crate::wording::Wording,
}

impl FnFacts {
    /// The function's source as whole lines: `source` starts at the function's column, so its
    /// first line is indented back to it.
    pub fn whole_lines(&self) -> String {
        format!(
            "{}{}",
            " ".repeat(self.column.saturating_sub(1)),
            self.source
        )
    }

    fn key(&self) -> (&str, usize, usize, &str) {
        (&self.path, self.line, self.column, &self.name)
    }
}

/// Merges facts from several compilation targets: sorted, and deduplicated by
/// location and name (the first occurrence in input order wins).
pub fn merge(mut facts: Vec<FnFacts>) -> Vec<FnFacts> {
    facts.sort_by(|a, b| a.key().cmp(&b.key()));
    facts.dedup_by(|a, b| a.key() == b.key());
    facts
}

#[cfg(test)]
pub fn sample(name: &str) -> FnFacts {
    FnFacts {
        id: format!("krate::{name}"),
        implements: None,
        path: "src/lib.rs".into(),
        line: 1,
        column: 1,
        name: name.into(),
        params: 0,
        param_list: vec![],
        has_self: false,
        statements: 1,
        top_statements: 2,
        complexity: None,
        source: format!("fn {name}() {{}}"),
        preceding_line: String::new(),
        mutations: vec![],
        calls: vec![],
        effects: vec![],
        edges: vec![],
        mutated_types: vec![],
        sig: None,
        guard_clauses: vec![],
        pdg: None,
        wording: Default::default(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn merge_sorts_and_dedupes() {
        let mut b = sample("b");
        b.path = "src/z.rs".into();
        let merged = merge(vec![b.clone(), sample("a"), sample("a")]);
        assert_eq!(merged.len(), 2);
        assert_eq!(merged[0].name, "a");
        assert_eq!(merged[1].path, "src/z.rs");
    }

    #[test]
    fn old_facts_without_sig_still_parse() {
        let mut value = serde_json::to_value(sample("a")).unwrap();
        value.as_object_mut().unwrap().remove("sig");
        let back: FnFacts = serde_json::from_value(value).unwrap();
        assert_eq!(back.sig, None);
    }

    #[test]
    fn pdg_is_optional_and_round_trips() {
        let mut f = sample("a");
        assert_eq!(
            serde_json::to_value(&f).unwrap()["pdg"],
            serde_json::Value::Null
        );
        f.pdg = Some(Pdg {
            nodes: vec![PdgNode {
                kind: NodeKind::Call,
                ty: None,
                callee_id: Some("k::x".into()),
                callee_sig: None,
                macro_name: None,
                lit_kind: None,
                detail: String::new(),
                line: 3,
            }],
            edges: vec![PdgEdge {
                from: 0,
                to: 0,
                kind: EdgeKind::Ctrl,
                arg_pos: 2,
            }],
        });
        let back: FnFacts = serde_json::from_str(&serde_json::to_string(&f).unwrap()).unwrap();
        assert_eq!(back, f);
        // Sparse nodes from older or leaner emitters parse thanks to `serde(default)`.
        let sparse: PdgNode = serde_json::from_str(r#"{"kind":"lit"}"#).unwrap();
        assert_eq!(sparse.line, 0);
    }

    #[test]
    fn merge_is_order_independent() {
        let mut other = sample("c");
        other.line = 9;
        let one = merge(vec![sample("a"), other.clone()]);
        let two = merge(vec![other, sample("a")]);
        assert_eq!(one, two);
    }
}

